using System;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 DataGridView mouldingEntries;
 readonly List<MouldingTakeoff> manualMouldings=new List<MouldingTakeoff>();
 void AddMouldingFinishes(){mouldingEntries=Grid(new[]{"ID","Description / location","Moulding profile / size (mm)","Length m / unit","Qty","Total length m","Status"},5);mouldingEntries.Columns[2].Width=260;SetDefaults(mouldingEntries,new Dictionary<int,string>{{4,"1"}});AddGrid("Moulding",mouldingEntries,"Enter additional moulding outside the door/window perimeter takeoff. Use the same profile and size in mm to combine totals. Do not re-enter automatic opening moulding here. Final quantity is linear metres, grouped by profile/size.");}
 void RecalculateMouldings(){manualMouldings.Clear();if(mouldingEntries==null)return;var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in mouldingEntries.Rows){if(row.IsNewRow)continue;row.Cells[5].Value=row.Cells[6].Value="";if(Empty(row))continue;try{var item=new MouldingTakeoff{Id=Cell(row,0),Description=Cell(row,1),Profile=Cell(row,2),Length=Number(row,3),Quantity=Count(row,4)};if(!ids.Add(item.Id))throw new Exception("Duplicate moulding ID.");double total=item.Total;manualMouldings.Add(item);Measure(row,5,total);row.Cells[6].Value="Estimated";}catch(Exception ex){row.Cells[6].Value=ex.Message;errors.Add("Moulding "+Cell(row,0)+": "+ex.Message);}}}
 List<BillQuantity> MouldingQuantities(){var entries=new List<BillQuantity>();foreach(var opening in openings.Where(o=>o.Exterior&&o.Material!="Manual")){string profile=string.IsNullOrWhiteSpace(opening.MouldingProfile)?"Unspecified size (assign opening moulding profile)":opening.MouldingProfile.Trim();entries.Add(new BillQuantity{Section=profile,Description=opening.Id+" | "+opening.Kind+" | "+opening.Description,Quantity=opening.MouldingLength,Unit="m"});}foreach(var item in manualMouldings)entries.Add(new BillQuantity{Section=item.Profile.Trim(),Description=item.Id+" | "+item.Description,Quantity=item.Total,Unit="m"});var totals=new List<BillQuantity>();foreach(var group in entries.GroupBy(e=>MouldingTakeoff.Key(e.Section)).OrderBy(g=>g.Key)){var total=new BillQuantity{Section="Moulding",Description="Moulding | "+group.First().Section,Quantity=group.Sum(e=>e.Quantity),Unit="m"};total.Sources.AddRange(MergeSources(group));totals.Add(total);}return totals;}
}
}
